Output20[Expected Approach] Space Optimized DP – O(n) Time and O(1) SpaceIn this approach, we observe that in order to find solution for a particular state, we only need the answer for just two previous states. Hence, we can store the results for the previous two states, and as we move forward, we keep updating them to compute the next values. This means keeping track of the last two states and using them to calculate the next one will help us to find the solution optimally, without using extra space.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int minCost(vector<int> &height)
{
    int n = height.size();

    if (n == 1)
        return 0;

    // Variables prev1 and prev2 to store the result
    // of last and second last states
    int prev2 = 0;
    int prev1 = abs(height[1] - height[0]);

    for (int i = 2; i < n; i++)
    {
        int curr = min(prev1 + abs(height[i] - height[i - 1]), prev2 + abs(height[i] - height[i - 2]));

        // Updating prev2 to previous result and
        // prev1 to current result
        prev2 = prev1;
        prev1 = curr;
    }

    // In the last iteration, final value
    // of curr is stored in  prev1
    return prev1;
}

int main()
{
    vector<int> height = {20, 30, 40, 20};
    cout << minCost(height);
    return 0;
}


