    for (let i = 2; i < n; i++) {
        let curr = Math.min(
            prev1 + Math.abs(height[i] - height[i - 1]),
            prev2 + Math.abs(height[i] - height[i - 2]));

        // Updating prev2 to previous result and
        // prev1 to current result
        prev2 = prev1;
        prev1 = curr;
    }

    // In the last iteration, final value
    // of curr is stored in  prev1
    return prev1;
}

